input.command:
cd out && cat > tz.ts <<'EOF'
const f = new Intl.DateTimeFormat("sv-SE",{timeZone:"America/Chicago",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"});
import * as T from "./transform.ts";
let bad=0;
for (let t=Date.UTC(2004,0,1); t<Date.UTC(2030,0,1); t+=1800_000*7) {
  const want=f.format(t).replace(" ","T");
  const r=T.transform([{folio:"0.1",id:"a",issuer:"x",patient:"p",effective:"",recorded:new Date(t).toISOString(),narrative:"",payload:{}} as any], want.slice(0,10));
  // in scope at its local date, not the day before
  const prevDay=new Date(Date.parse(want.slice(0,10))-86400000).toISOString().slice(0,10);
  void r; void prevDay;
}
EOF
sed -i 's/^function localDateTime/export function localDateTime/' transform.ts
cat > tz.ts <<'EOF'
import { localDateTime } from "./transform.ts";
const f = new Intl.DateTimeFormat("sv-SE",{timeZone:"America/Chicago",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"});
let bad=0;
for (let t=Date.UTC(2004,0,1); t<Date.UTC(2030,0,1); t+=60_000*17) if (f.format(t).replace(" ","T")!==localDateTime(t)) bad++;
console.log("mismatches", bad);
EOF
bun tz.ts; sed -i 's/^export function localDateTime/function localDateTime/' transform.ts; rm tz.ts

